"""Daytime-cluster blast table (rule: run 2026-10-24-0604 PREREG.md L1.5; inputs regenerated by run 2026-10-26-1727). Local (PST = UTC - 8 h) hour of day for (a) ComCat earthquakes within 50 km
of the mainshock over 2020-2025 (data/all_types_2020_2025_50km.csv) and (b) the matched filter's declustered real
detections inside the search span that are > 30 s from every ComCat event within 50 km (data/real_detections.json, all 385
templates, written by code/null_full.py summary; data/window_50km_alltypes.csv). Blasts cluster in working hours; the fraction in 08-17 local is compared with
10/24 = 0.417. Run from claim/."""
import os, sys, csv, json, glob, datetime as dt
CL = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")); D = os.path.join(CL, "data"); U = dt.timezone.utc
def ts(s): return dt.datetime.strptime(s[:23].replace("Z", ""), "%Y-%m-%dT%H:%M:%S.%f").replace(tzinfo=U).timestamp()
def hour(t): return (dt.datetime.fromtimestamp(t, U) - dt.timedelta(hours=8)).hour
cc = [ts(r["time"]) for r in csv.DictReader(open(os.path.join(D, "all_types_2020_2025_50km.csv"))) if r["type"] == "earthquake"]
T_MAIN = dt.datetime(2024, 12, 9, 23, 8, 31, tzinfo=U).timestamp(); SPAN = (T_MAIN + 300, T_MAIN + 72 * 3600)
EV = [ts(r["time"]) for r in csv.DictReader(open(os.path.join(D, "window_50km_alltypes.csv")))]
real = [d for d in json.load(open(os.path.join(D, "real_detections.json"))) if SPAN[0] <= d["t"] <= SPAN[1]]   # from code/null_full.py summary
keep = []
for d in sorted(real, key=lambda d: -d["ncc"]):
    if all(abs(d["t"] - k["t"]) > 2 for k in keep): keep.append(d)
added = [d["t"] for d in keep if min(abs(d["t"] - e) for e in EV) > 30]
for name, ts_ in (("ComCat earthquakes 2020-2025 within 50 km", cc), ("added detections (declustered, > 30 s from ComCat), search span", added)):
    h = [0] * 24
    for t in ts_: h[hour(t)] += 1
    day = sum(h[8:18]); print("%s: n %d, fraction in 08-17 PST %.3f (uniform 0.417)" % (name, len(ts_), day / len(ts_)))
    print("   by local hour 0..23:", h)
print("the event: 2024-12-09 23:20 UTC = 15:20 PST")
